import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 4

def design(feats):
    # Identify potential drivers based on t-statistics
    drivers = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'expression':
            t_stat = abs(feats.x[:, feats.column(fid)] @ feats.y)
            if t_stat > 1.96:
                drivers.append(fid)

    # If we have no strong drivers, return empty design
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Find correlated pairs
    corr_pairs = set()
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            if abs(np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]) >= 0.6:
                fid1, fid2 = feats.ids[i], feats.ids[j]
                corr_pairs.add((min(fid1, fid2), max(fid1, fid2)))

    # Build candidate features
    columns = list(set(drivers))
    products = []

    # Add interaction terms from correlated pairs
    for a, b in corr_pairs:
        if a in drivers and b in drivers:
            products.append((a, b))

    # Weighted score: sum of drivers with weights from mutual information
    mi_scores = mutual_info_classif(feats.x[:, [feats.column(fid) for fid in drivers]], feats.y)
    loadings = dict(zip(drivers, mi_scores))

    # Limit to MAX_DRIVERS
    if len(drivers) > MAX_DRIVERS:
        sorted_drivers = sorted(drivers, key=lambda d: loadings[d], reverse=True)
        drivers = sorted_drivers[:MAX_DRIVERS]
        loadings = {d: loadings[d] for d in drivers}

    return Design(
        drivers=tuple(drivers),
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )
